pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);

        // benign log: a contract whose fallback accepts the AddMessage call
        SilentLog log = new SilentLog();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));

        // Rule: once a log address was set before initialization, any admissible
        // Deposit must succeed. Mutant ignores SetLogFile, so Log is address(0)
        // and Deposit always reverts.
        assertTrue(ok);
    }
}

contract SilentLog {
    fallback() external {}
}

