pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // keep the log address at an account whose (unchecked) call cannot break the flow
        c.SetLogFile(actor);
        uint256 a = bound(amount, 1, 1 ether);
        uint256 b = bound(uint256(amount) >> 96 | (amount > 0 ? uint256(amount) % 1 ether + 1 : 1), 1, 1 ether);

        vm.deal(actor, a);
        vm.prank(actor);
        c.Deposit{value: a}();
        vm.deal(actor, b);
        vm.prank(actor);
        c.Deposit{value: b}();

        assertEq(c.balances(actor), a + b);
    }
}

