pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        // C requires a LogFile before Deposit can succeed; route it to a compatible sink.
        LogSink sink = new LogSink();
        bytes4 sel = bytes4(keccak256("SetLogFile(address)"));
        (bool ok,) = address(c).call(abi.encodeWithSelector(sel, address(sink)));
        require(ok, "SetLogFile failed");
    }

    function testFuzz_property(address actor, uint96 v1, uint96 v2) public {
        vm.assume(actor != address(0));
        v1 = uint96(bound(v1, 1, type(uint96).max));
        // second deposit is positive but no larger than the first
        v2 = uint96(bound(v2, 1, v1));

        vm.deal(actor, uint256(v1) + uint256(v2));

        vm.prank(actor);
        c.Deposit{value: v1}();
        uint256 beforeSecond = c.balances(actor);

        vm.prank(actor);
        c.Deposit{value: v2}();

        // General rule: any positive deposit strictly increases the depositor's balance.
        assertTrue(c.balances(actor) > beforeSecond);
    }
}

contract LogSink {
    function AddMessage(address, uint256, string calldata) external pure {
        // accept and ignore log messages so c's Deposit never reverts
    }
    receive() external payable {}
}

